#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
static const int MAX_SIZE = 5007;
static const i64 BIGNUM = 1000000000LL;
static const i64 BIGMOD = 1000000007LL;

struct TransportEdge {
    int start;
    int end;
    i64 quota;
    i64 fee;
    i64 routed;
    TransportEdge(int s, int e, i64 q, i64 f)
        : start(s), end(e), quota(q), fee(f), routed(0) {}
};

vector<TransportEdge> full_edge_list;
i64 d_ary[MAX_SIZE];
i64 phi_vec[MAX_SIZE];
vector<int> neighbor_map[MAX_SIZE];
int pred_edge[MAX_SIZE];

void bridge(int u, int v, i64 cap, i64 cost) {
    neighbor_map[u].emplace_back(full_edge_list.size());
    full_edge_list.emplace_back(u, v, cap, cost);
    neighbor_map[v].emplace_back(full_edge_list.size());
    full_edge_list.emplace_back(v, u, 0, -cost);
}

void setup_potential(int source, int nodes) {
    fill(phi_vec, phi_vec + MAX_SIZE, BIGNUM);
    phi_vec[source] = 0;
    for (int iter = 0; iter < nodes; ++iter) {
        for (size_t i = 0; i < full_edge_list.size(); ++i) {
            auto& e = full_edge_list[i];
            if (e.quota == e.routed) continue;
            if (phi_vec[e.start] == BIGNUM) continue;
            phi_vec[e.end] = min(phi_vec[e.end], phi_vec[e.start] + e.fee);
        }
    }
}

void relax_paths(int source) {
    fill(d_ary, d_ary + MAX_SIZE, BIGNUM);
    d_ary[source] = 0;
    set<pair<i64, int>> heap;
    heap.insert({0, source});
    while (!heap.empty()) {
        auto [cur, v] = *heap.begin();
        heap.erase(heap.begin());
        for (int eid : neighbor_map[v]) {
            auto& e = full_edge_list[eid];
            if (e.quota == e.routed) continue;
            int to = e.end;
            i64 wgt = e.fee + phi_vec[v] - phi_vec[to];
            if (d_ary[v] + wgt < d_ary[to]) {
                heap.erase({d_ary[to], to});
                d_ary[to] = d_ary[v] + wgt;
                pred_edge[to] = eid;
                heap.insert({d_ary[to], to});
            }
        }
    }
}

pair<i64, i64> min_cost_flow(int src, int dst) {
    setup_potential(src, 50);
    relax_paths(src);
    i64 flow_val = 0, cost_val = 0;
    while (d_ary[dst] != BIGNUM) {
        i64 flow_amt = numeric_limits<i64>::max();
        i64 seg_fee = 0;
        for (int cur = dst; cur != src; ) {
            int eid = pred_edge[cur];
            flow_amt = min(flow_amt, full_edge_list[eid].quota - full_edge_list[eid].routed);
            seg_fee += full_edge_list[eid].fee;
            cur = full_edge_list[eid].start;
        }
        flow_val += flow_amt;
        cost_val += flow_amt * seg_fee;
        for (int cur = dst; cur != src; ) {
            int eid = pred_edge[cur];
            full_edge_list[eid].routed += flow_amt;
            full_edge_list[eid ^ 1].routed -= flow_amt;
            cur = full_edge_list[eid].start;
        }
        relax_paths(src);
        for (int i = 0; i < MAX_SIZE; ++i) phi_vec[i] = d_ary[i];
    }
    return {cost_val, flow_val};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    vector<int> needs(n, 0);
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        needs[--x]++;
    }
    for (int i = 0; i < n; ++i) bridge(5000, i, needs[i], 0);
    for (int round = 0; round < m; ++round) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int lvl = 0; lvl < 99; ++lvl) {
            i64 fee = d;
            for (int rep = 0; rep < 50; ++rep) {
                bridge(u + lvl * 50, v + (lvl + 1) * 50, 1, fee);
                bridge(v + lvl * 50, u + (lvl + 1) * 50, 1, fee);
                fee += 2 * d;
            }
        }
    }
    for (int lvl = 0; lvl <= 99; ++lvl) {
        bridge(lvl * 50, 5001, numeric_limits<i64>::max(), c * lvl);
    }
    for (int i = 0; i < n; ++i) {
        for (int lvl = 0; lvl < 99; ++lvl) {
            bridge(i + lvl * 50, i + (lvl + 1) * 50, numeric_limits<i64>::max(), 0);
        }
    }
    auto [ans, flow] = min_cost_flow(5000, 5001);
    assert(flow == k);
    cout << ans;
    return 0;
}
